SELECT      c.id AS "Id do Curso",     c.fullname AS "Nome do Curso",     t.id AS "Id do Departamento",     t.name AS "Nome do Departamento",     COUNT(ue.id) AS "Total de usuários inscritos",     DATE_FORMAT(FROM_UNIXTIME(ue.timecreated), '%Y-%m-%d %H:00:00') AS "Grupo de Hora",     DATE_FORMAT(FROM_UNIXTIME(ue.timecreated), '%Y-%m-%d') AS "Grupo de Dias",     DATE_FORMAT(FROM_UNIXTIME(ue.timecreated), '%Y-%m') AS "Grupo de Mês",     DATE_FORMAT(FROM_UNIXTIME(ue.timecreated), '%Y') AS "Grupo de Ano" FROM      mdl_user_enrolments AS ue JOIN      mdl_enrol AS e ON ue.enrolid = e.id JOIN      mdl_course AS c ON e.courseid = c.id LEFT JOIN      mdl_tool_tenant_user AS tu ON tu.userid = ue.userid LEFT JOIN      mdl_tool_tenant AS t ON t.id = tu.tenantid LEFT JOIN      mdl_customfield_field AS cff ON cff.shortname = 'obs' LEFT JOIN      mdl_customfield_data AS cfd ON cfd.fieldid = cff.id      AND cfd.instanceid = c.id WHERE      c.visible = 1     AND (cfd.value IS NULL OR cfd.value != '1') GROUP BY      c.id,      c.fullname,      t.id,      t.name ORDER BY      "Total de usuários inscritos" DESC;
